function buildSoldProductsForRange(from, to){
  const sales = salesInRange(from,to);
  const map = new Map();
  const cutoff = getLocalDayBounds(to).end;
  sales.forEach(sale=>{
    const responsible=String(sale.responsible||sale.meta?.responsible||sale.createdBy||'SIN RESPONSABLE').trim();
    (sale.items||[]).forEach(item=>{
      const product=(STATE.products||[]).find(p=>String(p.id||'')===String(item.productId||''))||{id:item.productId||'',name:item.rawName||'Producto eliminado',barcode:'',category:''};
      const key=String(item.productId||product.id||product.name);
      if(!map.has(key)) map.set(key,{productId:key,name:product.name||'Producto',barcode:product.barcode||'',category:product.category||'',qty:0,amount:0,responsibles:new Set(),sales:new Set(),expectedStock:null});
      const row=map.get(key);
      row.qty+=Number(item.qty||0);
      row.amount+=Number(item.qty||0)*Number(item.unitPrice||0);
      row.responsibles.add(responsible);
      row.sales.add(String(sale.id||''));
      const root=getRootStockProduct(product);
      if(root){
        const rootExpected=getStockAtCutoff(root,cutoff);
        row.expectedStock=product.parentProductId ?Math.max(0,Math.floor((rootExpected*getLinkedFactor(root,product))+1e-9)):rootExpected;
      }
    });
  });
  return Array.from(map.values()).map(row=>({
    desde:from,hasta:to,productoId:row.productId,producto:row.name,codigo:row.barcode,categoria:row.category,
    cantidadVendida:Number(row.qty.toFixed(3)),precioPromedio:row.qty?Number((row.amount/row.qty).toFixed(2)):0,
    importeTotal:Number(row.amount.toFixed(2)),stockEsperadoAlCierre:row.expectedStock,
    responsables:Array.from(row.responsibles).join(', '),numeroVentas:row.sales.size
  })).sort((a,b)=>b.importeTotal-a.importeTotal||String(a.producto).localeCompare(String(b.producto),'es'));
}

