function normalizePurchaseForView(raw){
  if(!raw) return null;
  const itemsRaw = Array.isArray(raw.items) ?raw.items : [];
  const items = itemsRaw.map((it, idx)=>({
    line: Number(it.line || (idx + 1)),
    movementId: String(it.movementId || '').trim(),
    productId: it.productId || '',
    name: it.name || 'Producto',
    qty: Number(it.qty || 0),
    costPrice: Number(it.costPrice || 0),
    salePrice: Number(it.salePrice || 0),
    subtotal: Number(it.subtotal || (Number(it.qty||0) * Number(it.costPrice||0))),
    stockBefore: (it.stockBefore === 0 || it.stockBefore) ?Number(it.stockBefore) : null,
    stockAfter: (it.stockAfter === 0 || it.stockAfter) ?Number(it.stockAfter) : null,
    stockNumber: (it.stockNumber === 0 || it.stockNumber) ?Number(it.stockNumber) : null,
    parentUnit: String(it.parentUnit || '').trim(),
    subProductId: String(it.subProductId || '').trim(),
    subName: String(it.subName || '').trim(),
    subUnit: String(it.subUnit || '').trim(),
    subFactor: Number(it.subFactor || 0),
    subQty: Number(it.subQty || 0),
    subCostPrice: Number(it.subCostPrice || 0),
    subSalePrice: Number(it.subSalePrice || 0),
    subProducts: Array.isArray(it.subProducts) ?it.subProducts.map(sp => normalizeIngresoSubDraftItem(sp)) : []
  }));
  items.forEach(it => {
    if(it.subProducts.length === 0 && (it.subProductId || it.subName)){
      it.subProducts = [normalizeIngresoSubDraftItem({
        parentUnit: it.parentUnit || 'Unidad',
        subProductId: it.subProductId,
        subName: it.subName,
        subUnit: it.subUnit || 'Unidad',
        subFactor: Number(it.subFactor || 0),
        subQty: Number(it.subQty || (Number(it.qty || 0) * Number(it.subFactor || 0)) || 0),
        subCostPrice: Number(it.subCostPrice || 0),
        subSalePrice: Number(it.subSalePrice || 0)
      })];
    }
  });
  const totalCost = Number(raw.totalCost || items.reduce((acc, it)=> acc + Number(it.subtotal||0), 0));
  return {
    id: raw.id || uid(),
    docType: raw.docType || 'COMPROBANTE',
    docNumber: raw.docNumber || 'SIN-NUMERO',
    supplierName: raw.supplierName || raw.supplier || 'Proveedor',
    supplierRuc: raw.supplierRuc || raw.ruc || '',
    supplierId: raw.supplierId || '',
    note: raw.note || '',
    date: raw.date || (raw.createdAt ?String(raw.createdAt).slice(0,10) : todayYMD()),
    createdAt: raw.createdAt || '',
    totalCost,
    items
  };
}
